#include <map>
#include <iostream>

class ThrowingKey {}; // Placeholder for a key type or operation that might throw

void insert_safe(std::map<int, int>& m, int key, int value) {
    size_t old_size = m.size();
    try {
        // Strong Guarantee: If insert fails, m.size() == old_size
        m.insert({key, value}); 
    } catch (const std::bad_alloc& e) {
        // The container structure is guaranteed to be unchanged
        std::cerr << "Insert failed, size remains: " << m.size() << std::endl;
    }
}

int main() {
    std::map<int, int> data;
    data.insert({1, 10});
    insert_safe(data, 2, 20); 
    // If the insert failed due to exception, data remains valid and uncorrupted.
}
